def _get_response_format(self) -> Optional[Union[Dict, Type[BaseModel]]]:
    self.model = cast(Model, self.model)
    if self.response_model is None:
        return None
    else:
        json_response_format = {"type": "json_object"}

        if self.model.supports_native_structured_outputs:
            if not self.use_json_mode:
                log_debug("Setting Model.response_format to Agent.response_model")
                return self.response_model
            else:
                log_debug(
                    "Model supports native structured outputs but it is not enabled. Using JSON mode instead."
                )
                return json_response_format

        elif self.model.supports_json_schema_outputs:
            if self.use_json_mode:
                log_debug("Setting Model.response_format to JSON response mode")
                return {
                    "type": "json_schema",
                    "json_schema": {
                        "name": self.response_model.__name__,
                        "schema": self.response_model.model_json_schema(),
                    },
                }
            else:
                return None

        else:
            log_debug("Model does not support structured or JSON schema outputs.")
            return json_response_format

def load(
    self,
    recreate: bool = False,
    upsert: bool = True,
    skip_existing: bool = True,
    filters: Optional[Dict[str, Any]] = None,
) -> None:
    """Load the website contents to the vector db"""

    if self.vector_db is None:
        logger.warning("No vector db provided")
        return

    if self.reader is None:
        logger.warning("No reader provided")
        return

    if recreate:
        log_debug("Dropping collection")
        self.vector_db.drop()

    log_debug("Creating collection")
    self.vector_db.create()

    log_info("Loading knowledge base")

    # Given that the crawler needs to parse the URL before existence can be checked
    # We check if the website url exists in the vector db if recreate is False
    urls_to_read = self.urls.copy()
    if not recreate:
        for url in urls_to_read:
            log_debug(f"Checking if {url} exists in the vector db")
            if self.vector_db.name_exists(name=url):
                log_debug(f"Skipping {url} as it exists in the vector db")
                urls_to_read.remove(url)

    num_documents = 0
    for url in urls_to_read:
        if document_list := self.reader.read(url=url):
            # Filter out documents which already exist in the vector db
            if not recreate:
                document_list = [document for document in document_list if not self.vector_db.doc_exists(document)]
                if not document_list:
                    continue
            if upsert and self.vector_db.upsert_available():
                self.vector_db.upsert(documents=document_list, filters=filters)
            else:
                self.vector_db.insert(documents=document_list, filters=filters)
            num_documents += len(document_list)
            log_info(f"Loaded {num_documents} documents to knowledge base")

    if self.optimize_on is not None and num_documents > self.optimize_on:
        log_debug("Optimizing Vector DB")
        self.vector_db.optimize()

def _make_memories_and_summaries(
    self, run_messages: RunMessages, session_id: str, user_id: Optional[str] = None
) -> Iterator[TeamRunResponseEvent]:
    from concurrent.futures import ThreadPoolExecutor, as_completed

    self.run_response = cast(TeamRunResponse, self.run_response)
    self.memory = cast(Memory, self.memory)

    # Create a thread pool with a reasonable number of workers
    with ThreadPoolExecutor(max_workers=3) as executor:
        futures = []
        user_message_str = (
            run_messages.user_message.get_content_string() if run_messages.user_message is not None else None
        )
        if self.enable_user_memories and user_message_str is not None and user_message_str:
            futures.append(
                executor.submit(self.memory.create_user_memories, message=user_message_str, user_id=user_id)
            )

        # Update the session summary if needed
        if self.enable_session_summaries:
            futures.append(
                executor.submit(self.memory.create_session_summary, session_id=session_id, user_id=user_id)  # type: ignore
            )

        if futures:
            if self.stream_intermediate_steps:
                yield create_team_memory_update_started_event(from_run_response=self.run_response)

            # Wait for all operations to complete and handle any errors
            for future in as_completed(futures):
                try:
                    future.result()
                except Exception as e:
                    log_warning(f"Error in memory/summary operation: {str(e)}")

            if self.stream_intermediate_steps:
                yield create_team_memory_update_completed_event(from_run_response=self.run_response)

