            member_id (str): The ID of the member to transfer the task to.
            task_description (str): A clear and concise description of the task the member should achieve.
            expected_output (str): The expected output from the member (optional).
        Returns:
            str: The result of the delegated task.
        """

        # Find the member agent using the helper function
        result = self._find_member_by_id(member_id)
        if result is None:
            yield f"Member with ID {member_id} not found in the team or any subteams. Please choose the correct member from the list of members:\n\n{self.get_members_system_message_content(indent=0)}"
            return

        member_agent_index, member_agent = result
        self._initialize_member(member_agent, session_id=session_id)

        # 2. Determine team context to send
        if isinstance(self.memory, TeamMemory):
            self.memory = cast(TeamMemory, self.memory)
            team_context_str = None
            if self.enable_agentic_context:
                team_context_str = self.memory.get_team_context_str()

            team_member_interactions_str = None
            if self.share_member_interactions:
                team_member_interactions_str = self.memory.get_team_member_interactions_str()
                if context_images := self.memory.get_team_context_images():
                    images.extend([Image.from_artifact(img) for img in context_images])
                if context_videos := self.memory.get_team_context_videos():
                    videos.extend([Video.from_artifact(vid) for vid in context_videos])
                if context_audio := self.memory.get_team_context_audio():
                    audio.extend([Audio.from_artifact(aud) for aud in context_audio])
        else:
            self.memory = cast(Memory, self.memory)
            team_context_str = None
            if self.enable_agentic_context:
                team_context_str = self.memory.get_team_context_str(session_id=session_id)  # type: ignore

            team_member_interactions_str = None
            if self.share_member_interactions:
                team_member_interactions_str = self.memory.get_team_member_interactions_str(session_id=session_id)  # type: ignore
                if context_images := self.memory.get_team_context_images(session_id=session_id):  # type: ignore
                    images.extend([Image.from_artifact(img) for img in context_images])
                if context_videos := self.memory.get_team_context_videos(session_id=session_id):  # type: ignore
                    videos.extend([Video.from_artifact(vid) for vid in context_videos])
                if context_audio := self.memory.get_team_context_audio(session_id=session_id):  # type: ignore
                    audio.extend([Audio.from_artifact(aud) for aud in context_audio])

        # 3. Create the member agent task
        member_agent_task = "You are a member of a team of agents. Your goal is to complete the following task:"
        member_agent_task += f"\n\n<task>\n{task_description}\n</task>"

        if expected_output is not None:
            member_agent_task += f"\n\n<expected_output>\n{expected_output}\n</expected_output>"

        if team_context_str:
            member_agent_task += f"\n\n{team_context_str}"
        if team_member_interactions_str:
            member_agent_task += f"\n\n{team_member_interactions_str}"

        # Make sure for the member agent, we are using the agent logger
        use_agent_logger()

        if stream:
            member_agent_run_response_stream = await member_agent.arun(
                member_agent_task, images=images, videos=videos, audio=audio, files=files, stream=True
            )
            async for member_agent_run_response_chunk in member_agent_run_response_stream:
                check_if_run_cancelled(member_agent_run_response_chunk)
                if member_agent_run_response_chunk.content is not None:
                    yield member_agent_run_response_chunk.content
                elif (
                    member_agent_run_response_chunk.tools is not None
                    and len(member_agent_run_response_chunk.tools) > 0
                ):
                    yield ",".join([tool.get("content", "") for tool in member_agent_run_response_chunk.tools])
        else:
            member_agent_run_response = await member_agent.arun(
                member_agent_task, images=images, videos=videos, audio=audio, files=files, stream=False
            )
            check_if_run_cancelled(member_agent_run_response)

            if member_agent_run_response.content is None and (
                member_agent_run_response.tools is None or len(member_agent_run_response.tools) == 0
            ):
                yield "No response from the member agent."
            elif isinstance(member_agent_run_response.content, str):
                if len(member_agent_run_response.content.strip()) > 0:
                    yield member_agent_run_response.content

                # If the content is empty but we have tool calls
                elif member_agent_run_response.tools is not None and len(member_agent_run_response.tools) > 0:
                    yield ",".join([tool.get("content", "") for tool in member_agent_run_response.tools])
            elif issubclass(type(member_agent_run_response.content), BaseModel):
                try:
                    yield member_agent_run_response.content.model_dump_json(indent=2)  # type: ignore
                except Exception as e:
                    yield str(e)
            else:
                try:
                    import json

                    yield json.dumps(member_agent_run_response.content, indent=2)
                except Exception as e:
                    yield str(e)

        # Afterward, switch back to the team logger
        use_team_logger()

        # Update the memory
        member_name = member_agent.name if member_agent.name else f"agent_{member_agent_index}"
        if isinstance(self.memory, TeamMemory):
            self.memory = cast(TeamMemory, self.memory)
            self.memory.add_interaction_to_team_context(
                member_name=member_name,
                task=task_description,
                run_response=member_agent.run_response,  # type: ignore
            )
        else:
            self.memory = cast(Memory, self.memory)
            self.memory.add_interaction_to_team_context(
                session_id=session_id,
                member_name=member_name,
                task=task_description,
                run_response=member_agent.run_response,  # type: ignore
            )

        # Add the member run to the team run response
        self.run_response = cast(TeamRunResponse, self.run_response)
        self.run_response.add_member_run(member_agent.run_response)  # type: ignore

        # Update team session state
        self._update_team_session_state(member_agent)

        # Update the team media
        self._update_team_media(member_agent.run_response)  # type: ignore

    if async_mode:
        transfer_function = atransfer_task_to_member  # type: ignore
    else:
        transfer_function = transfer_task_to_member  # type: ignore

    transfer_func = Function.from_callable(transfer_function, strict=True)

    return transfer_func

def from_callable(cls, c: Callable, strict: bool = False) -> "Function":
    from inspect import getdoc, signature

    from agno.utils.json_schema import get_json_schema

    function_name = c.__name__
    parameters = {"type": "object", "properties": {}, "required": []}
    try:
        sig = signature(c)
        type_hints = get_type_hints(c)

        # If function has an the agent argument, remove the agent parameter from the type hints
        if "agent" in sig.parameters:
            del type_hints["agent"]
        if "team" in sig.parameters:
            del type_hints["team"]
        # log_info(f"Type hints for {function_name}: {type_hints}")

        # Filter out return type and only process parameters
        param_type_hints = {
            name: type_hints.get(name)
            for name in sig.parameters
            if name != "return" and name not in ["agent", "team"]
        }

        # Parse docstring for parameters
        param_descriptions: Dict[str, Any] = {}
        if docstring := getdoc(c):
            parsed_doc = parse(docstring)
            param_docs = parsed_doc.params

            if param_docs is not None:
                for param in param_docs:
                    param_name = param.arg_name
                    param_type = param.type_name
                    if param_type is None:
                        param_descriptions[param_name] = param.description
                    else:
                        param_descriptions[param_name] = f"({param_type}) {param.description}"

        # Get JSON schema for parameters only
        parameters = get_json_schema(
            type_hints=param_type_hints, param_descriptions=param_descriptions, strict=strict
        )

        # If strict=True mark all fields as required
        # See: https://platform.openai.com/docs/guides/structured-outputs/supported-schemas#all-fields-must-be-required
        if strict:
            parameters["required"] = [name for name in parameters["properties"] if name not in ["agent", "team"]]
        else:
            # Mark a field as required if it has no default value (this would include optional fields)
            parameters["required"] = [
                name
                for name, param in sig.parameters.items()
                if param.default == param.empty and name != "self" and name not in ["agent", "team"]
            ]

        # log_debug(f"JSON schema for {function_name}: {parameters}")
    except Exception as e:
        log_warning(f"Could not parse args for {function_name}: {e}", exc_info=True)

    entrypoint = cls._wrap_callable(c)

    return cls(
        name=function_name,
        description=get_entrypoint_docstring(entrypoint=c),
        parameters=parameters,
        entrypoint=entrypoint,
    )

def process_entrypoint(self, strict: bool = False):
    """Process the entrypoint and make it ready for use by an agent."""
    from inspect import getdoc, signature

    from agno.utils.json_schema import get_json_schema

    if self.skip_entrypoint_processing:
        if strict:
            self.process_schema_for_strict()
        return

    if self.entrypoint is None:
        return

    parameters = {"type": "object", "properties": {}, "required": []}

    params_set_by_user = False
    # If the user set the parameters (i.e. they are different from the default), we should keep them
    if self.parameters != parameters:
        params_set_by_user = True

    if self.requires_user_input:
        self.user_input_schema = self.user_input_schema or []

    try:
        sig = signature(self.entrypoint)
        type_hints = get_type_hints(self.entrypoint)

        # If function has an the agent argument, remove the agent parameter from the type hints
        if "agent" in sig.parameters:
            del type_hints["agent"]
        if "team" in sig.parameters:
            del type_hints["team"]
        # log_info(f"Type hints for {self.name}: {type_hints}")

        # Filter out return type and only process parameters
        excluded_params = ["return", "agent", "team"]
        if self.requires_user_input and self.user_input_fields:
            if len(self.user_input_fields) == 0:
                excluded_params.extend(list(type_hints.keys()))
            else:
                excluded_params.extend(self.user_input_fields)

        # Get filtered list of parameter types
        param_type_hints = {name: type_hints.get(name) for name in sig.parameters if name not in excluded_params}

        # Parse docstring for parameters
        param_descriptions = {}
        param_descriptions_clean = {}
        if docstring := getdoc(self.entrypoint):
            parsed_doc = parse(docstring)
            param_docs = parsed_doc.params

            if param_docs is not None:
                for param in param_docs:
                    param_name = param.arg_name
                    param_type = param.type_name

                    # TODO: We should use type hints first, then map param types in docs to json schema types.
                    # This is temporary to not lose information
                    param_descriptions[param_name] = f"({param_type}) {param.description}"
                    param_descriptions_clean[param_name] = param.description

        # If the function requires user input, we should set the user_input_schema to all parameters. The arguments provided by the model are filled in later.
        if self.requires_user_input:
            self.user_input_schema = [
                UserInputField(
                    name=name,
                    description=param_descriptions_clean.get(name),
                    field_type=type_hints.get(name, str),
                )
                for name in sig.parameters
            ]

        # Get JSON schema for parameters only
        parameters = get_json_schema(
            type_hints=param_type_hints, param_descriptions=param_descriptions, strict=strict
        )

        # If strict=True mark all fields as required
        # See: https://platform.openai.com/docs/guides/structured-outputs/supported-schemas#all-fields-must-be-required
        if strict:
            parameters["required"] = [name for name in parameters["properties"] if name not in excluded_params]
        else:
            # Mark a field as required if it has no default value
            parameters["required"] = [
                name
                for name, param in sig.parameters.items()
                if param.default == param.empty and name != "self" and name not in excluded_params
            ]

        if params_set_by_user:
            self.parameters["additionalProperties"] = False
            if strict:
                self.parameters["required"] = [
                    name for name in self.parameters["properties"] if name not in excluded_params
                ]
            else:
                # Mark a field as required if it has no default value
                self.parameters["required"] = [
                    name
                    for name, param in sig.parameters.items()
                    if param.default == param.empty and name != "self" and name not in excluded_params
                ]

        self.description = self.description or get_entrypoint_docstring(self.entrypoint)

        # log_debug(f"JSON schema for {self.name}: {parameters}")
    except Exception as e:
        log_warning(f"Could not parse args for {self.name}: {e}", exc_info=True)

    if not params_set_by_user:
        self.parameters = parameters

    try:
        self.entrypoint = self._wrap_callable(self.entrypoint)
    except Exception as e:
        log_warning(f"Failed to add validate decorator to entrypoint: {e}")

    parameters: dict = {
        "type": "object",
        "properties": {
            "json_path": {
                "type": "string",
                "description": """Path to the JSON file generated by insights_selection tool.
Contains chart insights data in format:
{
  "chartPath": string,
  "insights_id": number[]
}""",
            },
            "output_type": {
                "type": "string",
                "description": "Visualization output format selection",
                "default": "html",
                "enum": [
                    "png",    # Static image format
                    "html"    # Interactive web format (recommended)
                ],
            },
        },
        "required": ["json_path"],
    }

def load_chart_with_css(self, chart_path):
    # 读取 HTML 文件
    with open(chart_path, 'r', encoding='utf-8') as f:
        html_content = f.read()
    html_content = html_content.replace('`', "'")

    # 在 <head> 里插入 CSS
    css = """
    <style>
        body, html {
            margin: 0;
            padding: 0;
            height: 100%;
            overflow: hidden;
        }
        #chart-container {
            width: 100%;
            height: 100%;
        }
    </style>
    """

    # 如果原文件没有 <head>，直接插入到最前面
    if "<head>" in html_content:
        html_content = html_content.replace("<head>", "<head>" + css)
    else:
        html_content = css + html_content

    with open(chart_path, 'w', encoding='utf-8') as f:
        f.write(html_content)

def get_file_path(
    self,
    json_info: list[dict[str, str]],
    path_str: str,
    directory: str = None,
) -> list[str]:
    res = []
    for item in json_info:
        if os.path.exists(item[path_str]):
            res.append(item[path_str])
        elif os.path.exists(
            os.path.join(f"{directory or config.workspace_root}", item[path_str])
        ):
            res.append(
                os.path.join(
                    f"{directory or config.workspace_root}", item[path_str]
                )
            )
        else:
            raise Exception(f"No such file or directory: {item[path_str]}")
    return res

async def add_insights(
    self, json_info: list[dict[str, str]], output_type: str
) -> str:
    data_list = []
    chart_file_path = self.get_file_path(
        json_info, "chartPath", os.path.join(config.workspace_root, "visualization")
    )
    for index, item in enumerate(json_info):
        if "insights_id" in item:
            data_list.append(
                {
                    "file_name": os.path.basename(chart_file_path[index]).replace(
                        f".{output_type}", ""
                    ),
                    "insights_id": item["insights_id"],
                }
            )
    tasks = [
        self.invoke_vmind(
            insights_id=item["insights_id"],
            file_name=item["file_name"],
            output_type=output_type,
            task_type="insight",
        )
        for item in data_list
    ]
    results = await asyncio.gather(*tasks)
    error_list = []
    success_list = []
    for index, result in enumerate(results):
        chart_path = chart_file_path[index]
        if "error" in result and "chart_path" not in result:
            error_list.append(f"Error in {chart_path}: {result['error']}")
        else:
            success_list.append(chart_path)
            self.load_chart_with_css(chart_path)

    success_template = (
        f"# Charts Update with Insights\n{','.join(success_list)}"
        if len(success_list) > 0
        else ""
    )
    if len(error_list) > 0:
        return {
            "observation": f"# Error in chart insights:{'\n'.join(error_list)}\n{success_template}",
            "success": False,
        }
    else:
        return {"observation": f"{success_template}"}

