def _format_str_once(
    src_contents: str, *, mode: Mode, lines: Collection[tuple[int, int]] = ()
) -> str:
    if Preview.normalize_cr_newlines in mode:
        normalized_contents, _, newline_type = decode_bytes(
            src_contents.encode("utf-8"), mode
        )

        src_node = lib2to3_parse(
            normalized_contents.lstrip(), target_versions=mode.target_versions
        )
    else:
        src_node = lib2to3_parse(src_contents.lstrip(), mode.target_versions)

    dst_blocks: list[LinesBlock] = []
    if mode.target_versions:
        versions = mode.target_versions
    else:
        future_imports = get_future_imports(src_node)
        versions = detect_target_versions(src_node, future_imports=future_imports)

    line_generation_features = {
        feature
        for feature in {
            Feature.PARENTHESIZED_CONTEXT_MANAGERS,
            Feature.UNPARENTHESIZED_EXCEPT_TYPES,
        }
        if supports_feature(versions, feature)
    }
    normalize_fmt_off(src_node, mode, lines)
    if lines:
        # This should be called after normalize_fmt_off.
        convert_unchanged_lines(src_node, lines)

    line_generator = LineGenerator(mode=mode, features=line_generation_features)
    elt = EmptyLineTracker(mode=mode)
    split_line_features = {
        feature
        for feature in {
            Feature.TRAILING_COMMA_IN_CALL,
            Feature.TRAILING_COMMA_IN_DEF,
        }
        if supports_feature(versions, feature)
    }
    block: Optional[LinesBlock] = None
    for current_line in line_generator.visit(src_node):
        block = elt.maybe_empty_lines(current_line)
        dst_blocks.append(block)
        for line in transform_line(
            current_line, mode=mode, features=split_line_features
        ):
            block.content_lines.append(str(line))
    if dst_blocks:
        dst_blocks[-1].after = 0
    dst_contents = []
    for block in dst_blocks:
        dst_contents.extend(block.all_lines())
    if not dst_contents:
        if Preview.normalize_cr_newlines in mode:
            if "\n" in normalized_contents:
                return newline_type
        else:
            # Use decode_bytes to retrieve the correct source newline (CRLF or LF),
            # and check if normalized_content has more than one line
            normalized_content, _, newline = decode_bytes(
                src_contents.encode("utf-8"), mode
            )
            if "\n" in normalized_content:
                return newline
        return ""
    if Preview.normalize_cr_newlines in mode:
        return "".join(dst_contents).replace("\n", newline_type)
    else:
        return "".join(dst_contents)

def _format_str_once(
    src_contents: str, *, mode: Mode, lines: Collection[tuple[int, int]] = ()
) -> str:
    if Preview.normalize_cr_newlines in mode:
        normalized_contents, _, newline_type = decode_bytes(
            src_contents.encode("utf-8"), mode
        )

        src_node = lib2to3_parse(
            normalized_contents.lstrip(), target_versions=mode.target_versions
        )
    else:
        src_node = lib2to3_parse(src_contents.lstrip(), mode.target_versions)

    dst_blocks: list[LinesBlock] = []
    if mode.target_versions:
        versions = mode.target_versions
    else:
        future_imports = get_future_imports(src_node)
        versions = detect_target_versions(src_node, future_imports=future_imports)

    line_generation_features = {
        feature
        for feature in {
            Feature.PARENTHESIZED_CONTEXT_MANAGERS,
            Feature.UNPARENTHESIZED_EXCEPT_TYPES,
        }
        if supports_feature(versions, feature)
    }
    normalize_fmt_off(src_node, mode, lines)
    if lines:
        # This should be called after normalize_fmt_off.
        convert_unchanged_lines(src_node, lines)

    line_generator = LineGenerator(mode=mode, features=line_generation_features)
    elt = EmptyLineTracker(mode=mode)
    split_line_features = {
        feature
        for feature in {
            Feature.TRAILING_COMMA_IN_CALL,
            Feature.TRAILING_COMMA_IN_DEF,
        }
        if supports_feature(versions, feature)
    }
    block: Optional[LinesBlock] = None
    for current_line in line_generator.visit(src_node):
        block = elt.maybe_empty_lines(current_line)
        dst_blocks.append(block)
        for line in transform_line(
            current_line, mode=mode, features=split_line_features
        ):
            block.content_lines.append(str(line))
    if dst_blocks:
        dst_blocks[-1].after = 0
    dst_contents = []
    for block in dst_blocks:
        dst_contents.extend(block.all_lines())
    if not dst_contents:
        if Preview.normalize_cr_newlines in mode:
            if "\n" in normalized_contents:
                return newline_type
        else:
            # Use decode_bytes to retrieve the correct source newline (CRLF or LF),
            # and check if normalized_content has more than one line
            normalized_content, _, newline = decode_bytes(
                src_contents.encode("utf-8"), mode
            )
            if "\n" in normalized_content:
                return newline
        return ""
    if Preview.normalize_cr_newlines in mode:
        return "".join(dst_contents).replace("\n", newline_type)
    else:
        return "".join(dst_contents)

"""Return a tuple of (decoded_contents, encoding, newline).

`newline` is either CRLF or LF but `decoded_contents` is decoded with
universal newlines (i.e. only contains LF).
"""
srcbuf = io.BytesIO(src)
encoding, lines = tokenize.detect_encoding(srcbuf.readline)
if not lines:
    return "", encoding, "\n"

if Preview.normalize_cr_newlines in mode:
    if lines[0][-2:] == b"\r\n":
        if b"\r" in lines[0][:-2]:
            newline = "\r"
        else:
            newline = "\r\n"
    elif lines[0][-1:] == b"\n":
        if b"\r" in lines[0][:-1]:
            newline = "\r"
        else:
            newline = "\n"
    else:
        if b"\r" in lines[0]:
            newline = "\r"
        else:
            newline = "\n"
else:
    newline = "\r\n" if lines[0][-2:] == b"\r\n" else "\n"

srcbuf.seek(0)
with io.TextIOWrapper(srcbuf, encoding) as tiow:
    return tiow.read(), encoding, newline

def stdev(values):
    """
    Computes standard deviation of a list of numbers.

    # Reference: http://www.goldb.org/corestats.html

    >>> "%.3f" % stdev([0.9, 0.9, 0.9, 1.0, 0.8, 0.9])
    '0.063'
    """

    if not values or len(values) < 2:
        return None
    else:
        avg = average(values)
        _ = 1.0 * sum(pow((_ or 0) - avg, 2) for _ in values)
        return sqrt(_ / (len(values) - 1))

def test_json_adapter_formats_image_with_nested_images():
    class ImageWrapper(pydantic.BaseModel):
        images: list[dspy.Image]
        tag: list[str]

    class MySignature(dspy.Signature):
        image: ImageWrapper = dspy.InputField()
        text: str = dspy.OutputField()

    image1 = dspy.Image(url="https://example.com/image1.jpg")
    image2 = dspy.Image(url="https://example.com/image2.jpg")
