        if isinstance(environment.runner, MasterRunner):
            workers = []
            for worker in environment.runner.clients.values():
                workers.append(
                    {
                        "id": worker.id,
                        "state": worker.state,
                        "user_count": worker.user_count,
                        "cpu_usage": worker.cpu_usage,
                        "memory_usage": worker.memory_usage,
