def crawl_website(self, url: str, limit: Optional[int] = None) -> str:
    """Use this function to Crawls a website using Firecrawl.

    Args:
        url (str): The URL to crawl.
        limit (int): The maximum number of pages to crawl

    Returns:
        The results of the crawling.
    """
    params: Dict[str, Any] = {}
    if self.limit or limit:
        params["limit"] = self.limit or limit
    if self.formats:
        params["scrape_options"] = ScrapeOptions(formats=self.formats)  # type: ignore

    params["poll_interval"] = self.poll_interval

    crawl_result = self.app.crawl_url(url, **params)
    return json.dumps(crawl_result.model_dump(), cls=CustomJSONEncoder)

def search(self, query: str, limit: Optional[int] = None):
    """Use this function to search for the web using Firecrawl.

    Args:
        query (str): The query to search for.
        limit (int): The maximum number of results to return.
    """
    params: Dict[str, Any] = {}
    if self.limit or limit:
        params["limit"] = self.limit or limit
    if self.formats:
        params["scrape_options"] = ScrapeOptions(formats=self.formats)  # type: ignore
    if self.search_params:
        params.update(self.search_params)

    search_result = self.app.search(query, **params)
    if search_result.success:
        return json.dumps(search_result.data, cls=CustomJSONEncoder)
    else:
        return "Error searching with the Firecrawl tool: " + search_result.error

def apply_locale(self, locale, out_fn=None, keyname="LANG"):
    try:
        subp.subp(
            [
                "/usr/bin/raspi-config",
                "nonint",
                "do_change_locale",
                f"{locale}",
            ]
        )
    except subp.ProcessExecutionError:
        if not locale.endswith(".UTF-8"):
            LOG.info("Trying to set locale %s.UTF-8", locale)
            subp.subp(
                [
                    "/usr/bin/raspi-config",
                    "nonint",
                    "do_change_locale",
                    f"{locale}.UTF-8",
                ]
            )
        else:
            LOG.error("Failed to set locale %s")

def handle(name: str, cfg: Config, cloud: Cloud, args: list) -> None:
    """
    See doc/examples/cloud-config-disk-setup.txt for documentation on the
    format.
    """
    device_aliases = cfg.get("device_aliases", {})

    def alias_to_device(cand):
        name = device_aliases.get(cand)
        return cloud.device_name_to_device(name or cand) or name

    disk_setup = cfg.get("disk_setup")
    if isinstance(disk_setup, dict):
        update_disk_setup_devices(disk_setup, alias_to_device)
        LOG.debug("Partitioning disks: %s", str(disk_setup))
        for disk, definition in disk_setup.items():
            if not isinstance(definition, dict):
                LOG.warning("Invalid disk definition for %s", disk)
                continue

            try:
                with performance.Timed(
                    f"Creating partition on {disk}",
                ):
                    mkpart(disk, definition)
            except Exception as e:
                util.logexc(LOG, "Failed partitioning operation\n%s" % e)

    fs_setup = cfg.get("fs_setup")
    if isinstance(fs_setup, list):
        LOG.debug("setting up filesystems: %s", str(fs_setup))
        update_fs_setup_devices(fs_setup, alias_to_device)
        for definition in fs_setup:
            if not isinstance(definition, dict):
                LOG.warning("Invalid file system definition: %s", definition)
                continue

            try:
                with performance.Timed("Creating new filesystem"):
                    mkfs(definition)
            except Exception as e:
                util.logexc(LOG, "Failed during filesystem operation\n%s" % e)

