def read_parttbl(device):
    """
    `Partprobe` is preferred over `blkdev` since it is more reliably
    able to probe the partition table.
    """
    partprobe = "partprobe"
    if subp.which(partprobe):
        probe_cmd = [partprobe, device]
    else:
        probe_cmd = ["blockdev", "--rereadpt", device]
    util.udevadm_settle()
    try:
        subp.subp(probe_cmd)
    except Exception as e:
        util.logexc(LOG, "Failed reading the partition table %s" % e)

    util.udevadm_settle()

def auto_loop_factory(use_subprocess: bool = False) -> Callable[[], asyncio.AbstractEventLoop]:
    try:
        if sys.platform == "win32":  # pragma: py-win32
            from uvicorn.loops.winloop import winloop_loop_factory as loop_factory
        else:  # pragma: py-not-win32
            from uvicorn.loops.uvloop import uvloop_loop_factory as loop_factory
    except ImportError:  # pragma: no cover
        from uvicorn.loops.asyncio import asyncio_loop_factory as loop_factory
    return loop_factory(use_subprocess=use_subprocess)

def conditional_process_temp_frame(temp_frame_path : str, frame_number : int, output_video_fps : float) -> bool:
	source_vision_frames = read_static_images(state_manager.get_item('source_paths'))
	source_audio_path = get_first(filter_audio_paths(state_manager.get_item('source_paths')))
	target_vision_frame = read_static_image(temp_frame_path, 'rgba')
	temp_vision_frame = target_vision_frame.copy()
	temp_vision_mask = extract_vision_mask(temp_vision_frame)

	if is_video(state_manager.get_item('target_path')):
		reference_vision_frame = read_static_video_frame(state_manager.get_item('target_path'), state_manager.get_item('reference_frame_number'))
	else:
		temp_image_path = get_temp_file_path(state_manager.get_item('target_path'))
		reference_vision_frame = read_static_image(temp_image_path)

	source_audio_frame = get_audio_frame(source_audio_path, output_video_fps, frame_number)
	source_voice_frame = get_voice_frame(source_audio_path, output_video_fps, frame_number)

	if not numpy.any(source_audio_frame):
		source_audio_frame = create_empty_audio_frame()
	if not numpy.any(source_voice_frame):
		source_voice_frame = create_empty_audio_frame()

	for processor_module in get_processors_modules(state_manager.get_item('processors')):
		temp_vision_frame, temp_vision_mask = processor_module.process_frame(
		{
			'reference_vision_frame': reference_vision_frame,
			'source_vision_frames': source_vision_frames,
			'source_audio_frame': source_audio_frame,
			'source_voice_frame': source_voice_frame,
			'target_vision_frame': target_vision_frame[:, :, :3],
			'temp_vision_frame': temp_vision_frame[:, :, :3],
			'temp_vision_mask': temp_vision_mask
		})

	temp_vision_frame = conditional_merge_vision_mask(temp_vision_frame, temp_vision_mask)
	return write_image(temp_frame_path, temp_vision_frame)

def process_frames() -> ErrorCode:
	source_audio_path = get_first(filter_audio_paths(state_manager.get_item('source_paths')))
	audio_frame_total = count_audio_frame_total(source_audio_path, 25.0)
	output_video_fps = state_manager.get_item('output_video_fps')
	temp_frame_paths = get_temp_frame_sequence_paths(state_manager.get_item('target_path'), audio_frame_total, '%08d')

	if temp_frame_paths:
		with tqdm(total = len(temp_frame_paths), desc = translator.get('processing'), unit = 'frame', ascii = ' =', disable = state_manager.get_item('log_level') in [ 'warn', 'error' ]) as progress:
			progress.set_postfix(execution_providers = state_manager.get_item('execution_providers'))

			with ThreadPoolExecutor(max_workers = state_manager.get_item('execution_thread_count')) as executor:
				futures = []

				for frame_number, temp_frame_path in enumerate(temp_frame_paths):
					future = executor.submit(conditional_process_temp_frame, temp_frame_path, frame_number, output_video_fps)
					futures.append(future)

				for future in as_completed(futures):
					if is_process_stopping():
						for __future__ in futures:
							__future__.cancel()

					if not future.cancelled():
						future.result()
						progress.update()

		for processor_module in get_processors_modules(state_manager.get_item('processors')):
			processor_module.post_process()

		if is_process_stopping():
			return 4
	else:
		logger.error(translator.get('temp_frames_not_found'), __name__)
		return 1
	return 0

def replace_audio() -> ErrorCode:
	source_audio_path = get_first(filter_audio_paths(state_manager.get_item('source_paths')))

	if ffmpeg.replace_audio(state_manager.get_item('target_path'), source_audio_path, state_manager.get_item('output_path')):
		logger.debug(translator.get('replacing_audio_succeeded'), __name__)
	else:
		if is_process_stopping():
			return 4
		logger.warn(translator.get('replacing_audio_skipped'), __name__)
		temp_video_path = get_temp_file_path(state_manager.get_item('target_path'))
		temp_video_path = os.path.splitext(temp_video_path)[0] + '.mp4'
		move_file(temp_video_path, state_manager.get_item('output_path'))
	return 0

def get_locustfiles_locally(options):
    if options.locustfile == "-":
        locustfile_list = retrieve_locustfiles_from_master(options)
    else:
        locustfile_list = [f.strip() for f in options.locustfile.split(",")]

    return parse_locustfile_paths(locustfile_list)

def parse_locustfiles_from_master(locustfile_sources) -> list[str]:
    locustfiles = []

    for source in locustfile_sources:
        if "contents" in source:
            filename = source["filename"]
            file_contents = source["contents"]

            with open(os.path.join(tempfile.gettempdir(), filename), "w", encoding="utf-8") as locustfile:
                locustfile.write(file_contents)

            locustfiles.append(locustfile.name)
        else:
            locustfiles.append(source)

    return locustfiles

def retrieve_locustfiles_from_master(options) -> list[str]:
    if not options.worker:
        sys.stderr.write(
            "locustfile was set to '-' (meaning to download from master) but --worker was not specified.\n"
        )
        sys.exit(1)
    # having this in argument_parser module is a bit weird, but it needs to be done early
    locustfile_sources = download_locustfile_from_master(options.master_host, options.master_port)
    return parse_locustfiles_from_master(locustfile_sources)

class TestProcess:
    """
    Wraps a subprocess for testing purposes.
    """

    __test__ = False

    def __init__(
        self,
        command: str,
        *,
        expect_return_code: int | None = 0,
        sigint_on_exit: bool = True,
        expect_timeout: int = 5,
        use_pty: bool = False,
        join_timeout: int = 1,
    ):
        self.proc: subprocess.Popen[str]
        self._terminated = False
        self._failed = False

        self.expect_return_code = expect_return_code
        self.expect_timeout = expect_timeout
        self.sigint_on_exit = sigint_on_exit
        self.join_timeout = join_timeout

        self.stderr_output: list[str] = []
        self.stdout_output: list[str] = []
        self._stderr_cursor: int = 0  # Used for stateful log matching
        self._stdout_cursor: int = 0

        self.use_pty: bool = use_pty
        # Create PTY pair
        if self.use_pty:
            if IS_WINDOWS:
                raise Exception("termios doesn't exist on windows, and thus we cannot import pty")

            import pty

            self.stdin_m, self.stdin_s = pty.openpty()

        self.proc = subprocess.Popen(
            shlex.split(command) if not IS_WINDOWS else command.split(" "),
            env={"PYTHONUNBUFFERED": "1", **os.environ},
            stdin=self.stdin_s if self.use_pty else None,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
        )

        def _consume_output(source: IO[str], to: list[str]):
            for line in iter(source.readline, ""):
                line = line.rstrip("\n")
                to.append(line)

        self.stdout_reader = gevent.spawn(_consume_output, self.proc.stdout, self.stdout_output)
        self.stderr_reader = gevent.spawn(_consume_output, self.proc.stderr, self.stderr_output)

    def on_fail(self, reason: str = ""):
        __tracebackhide__ = True
        if self._failed:
            return
        self._failed = True
        for line in self.stderr_output:
            print(line)
        pytest.fail(reason)

    def __enter__(self) -> "TestProcess":
        return self

    def __exit__(self, *_) -> None:
        self.close()

    def close(self) -> None:
        if self.use_pty:
            os.close(self.stdin_m)
            os.close(self.stdin_s)

        try:
            if self.sigint_on_exit and not self._terminated:
                self.terminate()
            proc_return_code = self.proc.wait(timeout=self.join_timeout)

            # Locust does not perform a graceful shutdown on Windows since we send SIGTERM
            if not IS_WINDOWS and self.expect_return_code is not None and proc_return_code != self.expect_return_code:
                self.on_fail(
                    f"Process exited with return code {proc_return_code}. Expected {self.expect_return_code} ({proc_return_code} != {self.expect_return_code})"
                )
        except subprocess.TimeoutExpired:
            self.proc.kill()
            self.proc.wait()
            self.on_fail(f"Process took more than {self.join_timeout} seconds to terminate.")

        self.stdout_reader.join(timeout=self.join_timeout)
        self.stderr_reader.join(timeout=self.join_timeout)

    # Check output logs from last found (stateful)
    def expect(self, to_expect, *, stream="stderr"):
        __tracebackhide__ = True

        if stream == "stdout":
            buffer = self.stdout_output
            cursor = self._stdout_cursor
        else:
            buffer = self.stderr_output
            cursor = self._stderr_cursor

        start_time = time.time()
        while time.time() - start_time < self.expect_timeout:
            new_lines = buffer[cursor:]
            for idx, line in enumerate(new_lines):
                if to_expect in line:
                    cursor += idx + 1
                    return
            time.sleep(0.05)

        self.on_fail(f"Timed out waiting for '{to_expect}' after {self.expect_timeout} seconds. Got {buffer[-5:]}")

    # Check all output logs (stateless)
    def expect_any(self, to_expect, *, stream="stderr"):
        __tracebackhide__ = True

        if stream == "stdout":
            buffer = self.stdout_output
        else:
            buffer = self.stderr_output

        if any(to_expect in line for line in buffer):
            return

        self.on_fail(f"Did not see expected message: '{to_expect}'. Got {buffer[-5:]}")

    def not_expect_any(self, to_not_expect, *, stream="stderr"):
        __tracebackhide__ = True

        if stream == "stdout":
            buffer = self.stdout_output
        else:
            buffer = self.stderr_output

        if any(to_not_expect in line for line in buffer):
            self.on_fail(f"Found unexpected message: '{to_not_expect}'.")

    def send_input(self, content: str):
        if self.use_pty:
            os.write(self.stdin_m, content.encode())
        else:
            raise Exception("Cannot send input to proccess without pty.")

    def terminate(self):
        if IS_WINDOWS:
            # Signals are hard on Windows
            sig = signal.SIGTERM
        else:
            sig = signal.SIGINT

        self.proc.send_signal(sig)
        self._terminated = True

def send_input(self, content: str):
    if self.use_pty:
        os.write(self.stdin_m, content.encode())
    else:
        raise Exception("Cannot send input to proccess without pty.")

