def test_cryptoprice_prefetch_with_saved_parameters(self, mock_mongo_db):
    """Test that cryptoprice tool is pre-fetched with saved parameter values from MongoDB structure"""
    from application.api.answer.services.stream_processor import StreamProcessor
    from application.core.settings import settings
    from unittest.mock import patch, MagicMock

    # Setup MongoDB with cryptoprice tool configuration
    # NOTE: The collection is called "user_tools" not "tools"
    tools_collection = mock_mongo_db[settings.MONGO_DB_NAME]["user_tools"]
    tool_id = ObjectId()

    tools_collection.insert_one(
        {
            "_id": tool_id,
            "name": "cryptoprice",
            "user": "user_123",
            "status": True,  # Must be True for tool to be included
            "actions": [
                {
                    "name": "cryptoprice_get",
                    "description": "Get cryptocurrency price",
                    "parameters": {
                        "type": "object",
                        "properties": {
                            "symbol": {
                                "type": "string",
                                "description": "Crypto symbol",
                                "value": "BTC"  # Saved value in MongoDB
                            },
                            "currency": {
                                "type": "string",
                                "description": "Currency for price",
                                "value": "USD"  # Saved value in MongoDB
                            }
                        },
                        "required": ["symbol", "currency"]
                    }
                }
            ],
            "config": {
                "token": ""
            }
        }
    )

    request_data = {
        "question": "What is the price of Bitcoin?",
        "tools": [str(tool_id)]
    }

    processor = StreamProcessor(request_data, {"sub": "user_123"})
    processor._required_tool_actions = {"cryptoprice": {"cryptoprice_get"}}

    # Mock the ToolManager and tool instance
    with patch("application.agents.tools.tool_manager.ToolManager") as mock_manager_class:
        mock_manager = MagicMock()
        mock_manager_class.return_value = mock_manager

        # Mock the tool instance returned by load_tool
        mock_tool = MagicMock()
        mock_manager.load_tool.return_value = mock_tool

        # Mock get_actions_metadata on the tool instance
        mock_tool.get_actions_metadata.return_value = [
            {
                "name": "cryptoprice_get",
                "description": "Get cryptocurrency price",
                "parameters": {
                    "type": "object",
                    "properties": {
                        "symbol": {"type": "string", "description": "Crypto symbol"},
                        "currency": {"type": "string", "description": "Currency for price"}
                    },
                    "required": ["symbol", "currency"]
                }
            }
        ]

        # Mock execute_action on the tool instance to return price data
        mock_tool.execute_action.return_value = {
            "status_code": 200,
            "price": 45000.50,
            "message": "Price of BTC in USD retrieved successfully."
        }

        # Execute pre-fetch
        tools_data = processor.pre_fetch_tools()

        # Verify the tool was called
        assert mock_tool.execute_action.called

        # Verify it was called with the saved parameters from MongoDB
        call_args = mock_tool.execute_action.call_args
        assert call_args is not None

        # Check action name uses the full metadata name for execution
        assert call_args[0][0] == "cryptoprice_get"

        # Check kwargs contain saved values
        kwargs = call_args[1]
        assert kwargs.get("symbol") == "BTC"
        assert kwargs.get("currency") == "USD"

        # Verify tools_data structure
        assert "cryptoprice" in tools_data
        # Results are exposed under the full action name
        assert "cryptoprice_get" in tools_data["cryptoprice"]
        assert tools_data["cryptoprice"]["cryptoprice_get"]["price"] == 45000.50

def transform_request_body(
    cls, text: str, optional_params: dict
) -> AmazonNovaCanvasRequestBase:
    """
    Transform the request body for Amazon Nova Canvas model
    """
    task_type = optional_params.pop("taskType", "TEXT_IMAGE")
    image_generation_config = optional_params.pop("imageGenerationConfig", {})
    image_generation_config = {**image_generation_config, **optional_params}
    if task_type == "TEXT_IMAGE":
        text_to_image_params: Dict[str, Any] = image_generation_config.pop(
            "textToImageParams", {}
        )
        text_to_image_params = {"text": text, **text_to_image_params}
        try:
            text_to_image_params_typed = AmazonNovaCanvasTextToImageParams(
                **text_to_image_params  # type: ignore
            )
        except Exception as e:
            raise ValueError(
                f"Error transforming text to image params: {e}. Got params: {text_to_image_params}, Expected params: {AmazonNovaCanvasTextToImageParams.__annotations__}"
            )

        try:
            image_generation_config_typed = AmazonNovaCanvasImageGenerationConfig(
                **image_generation_config
            )
        except Exception as e:
            raise ValueError(
                f"Error transforming image generation config: {e}. Got params: {image_generation_config}, Expected params: {AmazonNovaCanvasImageGenerationConfig.__annotations__}"
            )

        return AmazonNovaCanvasTextToImageRequest(
            textToImageParams=text_to_image_params_typed,
            taskType=task_type,
            imageGenerationConfig=image_generation_config_typed,
        )
    if task_type == "COLOR_GUIDED_GENERATION":
        color_guided_generation_params: Dict[
            str, Any
        ] = image_generation_config.pop("colorGuidedGenerationParams", {})
        color_guided_generation_params = {
            "text": text,
            **color_guided_generation_params,
        }
        try:
            color_guided_generation_params_typed = AmazonNovaCanvasColorGuidedGenerationParams(
                **color_guided_generation_params  # type: ignore
            )
        except Exception as e:
            raise ValueError(
                f"Error transforming color guided generation params: {e}. Got params: {color_guided_generation_params}, Expected params: {AmazonNovaCanvasColorGuidedGenerationParams.__annotations__}"
            )

        try:
            image_generation_config_typed = AmazonNovaCanvasImageGenerationConfig(
                **image_generation_config
            )
        except Exception as e:
            raise ValueError(
                f"Error transforming image generation config: {e}. Got params: {image_generation_config}, Expected params: {AmazonNovaCanvasImageGenerationConfig.__annotations__}"
            )

        return AmazonNovaCanvasColorGuidedRequest(
            taskType=task_type,
