def _log_langfuse_v2(  # noqa: PLR0915
    self,
    user_id: Optional[str],
    metadata: dict,
    litellm_params: dict,
    output: Optional[Union[str, dict, list]],
    start_time: Optional[datetime],
    end_time: Optional[datetime],
    kwargs: dict,
    optional_params: dict,
    input: Optional[dict],
    response_obj,
    level: str,
    litellm_call_id: Optional[str],
) -> tuple:
    verbose_logger.debug("Langfuse Layer Logging - logging to langfuse v2")

    try:
        metadata = metadata or {}
        standard_logging_object: Optional[StandardLoggingPayload] = cast(
            Optional[StandardLoggingPayload],
            kwargs.get("standard_logging_object", None),
        )
        tags = (
            self._get_langfuse_tags(standard_logging_object=standard_logging_object)
            if self._supports_tags()
            else []
        )

        if standard_logging_object is None:
            end_user_id = None
            prompt_management_metadata: Optional[
                StandardLoggingPromptManagementMetadata
            ] = None
        else:
            end_user_id = standard_logging_object["metadata"].get(
                "user_api_key_end_user_id", None
            )

            prompt_management_metadata = cast(
                Optional[StandardLoggingPromptManagementMetadata],
                standard_logging_object["metadata"].get(
                    "prompt_management_metadata", None
                ),
            )

        # Clean Metadata before logging - never log raw metadata
        # the raw metadata can contain circular references which leads to infinite recursion
        # we clean out all extra litellm metadata params before logging
        clean_metadata: Dict[str, Any] = {}
        if prompt_management_metadata is not None:
            clean_metadata[
                "prompt_management_metadata"
            ] = prompt_management_metadata
        if isinstance(metadata, dict):
            for key, value in metadata.items():
                # generate langfuse tags - Default Tags sent to Langfuse from LiteLLM Proxy
                if (
                    litellm.langfuse_default_tags is not None
                    and isinstance(litellm.langfuse_default_tags, list)
                    and key in litellm.langfuse_default_tags
                ):
                    tags.append(f"{key}:{value}")

                # clean litellm metadata before logging
                if key in [
                    "headers",
                    "endpoint",
                    "caching_groups",
                    "previous_models",
                ]:
                    continue
                else:
                    clean_metadata[key] = value

        # Add default langfuse tags
        tags = self.add_default_langfuse_tags(
            tags=tags, kwargs=kwargs, metadata=metadata
        )

        session_id = clean_metadata.pop("session_id", None)
        trace_name = cast(Optional[str], clean_metadata.pop("trace_name", None))
        trace_id = clean_metadata.pop("trace_id", litellm_call_id)
        existing_trace_id = clean_metadata.pop("existing_trace_id", None)
        update_trace_keys = cast(list, clean_metadata.pop("update_trace_keys", []))
        debug = clean_metadata.pop("debug_langfuse", None)
        mask_input = clean_metadata.pop("mask_input", False)
        mask_output = clean_metadata.pop("mask_output", False)

        clean_metadata = redact_user_api_key_info(metadata=clean_metadata)

        if trace_name is None and existing_trace_id is None:
            # just log `litellm-{call_type}` as the trace name
            ## DO NOT SET TRACE_NAME if trace-id set. this can lead to overwriting of past traces.
            trace_name = f"litellm-{kwargs.get('call_type', 'completion')}"

        if existing_trace_id is not None:
            trace_params: Dict[str, Any] = {"id": existing_trace_id}

            # Update the following keys for this trace
            for metadata_param_key in update_trace_keys:
                trace_param_key = metadata_param_key.replace("trace_", "")
                if trace_param_key not in trace_params:
                    updated_trace_value = clean_metadata.pop(
                        metadata_param_key, None
                    )
                    if updated_trace_value is not None:
                        trace_params[trace_param_key] = updated_trace_value

            # Pop the trace specific keys that would have been popped if there were a new trace
            for key in list(
                filter(lambda key: key.startswith("trace_"), clean_metadata.keys())
            ):
                clean_metadata.pop(key, None)

            # Special keys that are found in the function arguments and not the metadata
            if "input" in update_trace_keys:
                trace_params["input"] = (
                    input if not mask_input else "redacted-by-litellm"
                )
            if "output" in update_trace_keys:
                trace_params["output"] = (
                    output if not mask_output else "redacted-by-litellm"
                )
        else:  # don't overwrite an existing trace
            trace_params = {
                "id": trace_id,
                "name": trace_name,
                "session_id": session_id,
                "input": input if not mask_input else "redacted-by-litellm",
                "version": clean_metadata.pop(
                    "trace_version", clean_metadata.get("version", None)
                ),  # If provided just version, it will applied to the trace as well, if applied a trace version it will take precedence
                "user_id": end_user_id,
            }
            for key in list(
                filter(lambda key: key.startswith("trace_"), clean_metadata.keys())
            ):
                trace_params[key.replace("trace_", "")] = clean_metadata.pop(
                    key, None
                )

            if level == "ERROR":
                trace_params["status_message"] = output
            else:
                trace_params["output"] = (
                    output if not mask_output else "redacted-by-litellm"
                )

        if debug is True or (isinstance(debug, str) and debug.lower() == "true"):
            if "metadata" in trace_params:
                # log the raw_metadata in the trace
                trace_params["metadata"]["metadata_passed_to_litellm"] = metadata
            else:
                trace_params["metadata"] = {"metadata_passed_to_litellm": metadata}

        cost = kwargs.get("response_cost", None)
        verbose_logger.debug(f"trace: {cost}")

        clean_metadata["litellm_response_cost"] = cost
        if standard_logging_object is not None:
            clean_metadata["hidden_params"] = standard_logging_object[
                "hidden_params"
            ]

        if (
            litellm.langfuse_default_tags is not None
            and isinstance(litellm.langfuse_default_tags, list)
            and "proxy_base_url" in litellm.langfuse_default_tags
        ):
            proxy_base_url = os.environ.get("PROXY_BASE_URL", None)
            if proxy_base_url is not None:
                tags.append(f"proxy_base_url:{proxy_base_url}")

        api_base = litellm_params.get("api_base", None)
        if api_base:
            clean_metadata["api_base"] = api_base

        vertex_location = kwargs.get("vertex_location", None)
        if vertex_location:
            clean_metadata["vertex_location"] = vertex_location

        aws_region_name = kwargs.get("aws_region_name", None)
        if aws_region_name:
            clean_metadata["aws_region_name"] = aws_region_name

        if self._supports_tags():
            if "cache_hit" in kwargs:
                if kwargs["cache_hit"] is None:
                    kwargs["cache_hit"] = False
                clean_metadata["cache_hit"] = kwargs["cache_hit"]
            if existing_trace_id is None:
                trace_params.update({"tags": tags})

        proxy_server_request = litellm_params.get("proxy_server_request", None)
        if proxy_server_request:
            proxy_server_request.get("method", None)
            proxy_server_request.get("url", None)
            headers = proxy_server_request.get("headers", None)
            clean_headers = {}
            if headers:
                for key, value in headers.items():
                    # these headers can leak our API keys and/or JWT tokens
                    if key.lower() not in ["authorization", "cookie", "referer"]:
                        clean_headers[key] = value

            # clean_metadata["request"] = {
            #     "method": method,
            #     "url": url,
            #     "headers": clean_headers,
            # }
        trace = self.Langfuse.trace(**trace_params)

        # Log provider specific information as a span
        log_provider_specific_information_as_span(trace, clean_metadata)

        generation_id = None
        usage = None
        if response_obj is not None:
            if (
                hasattr(response_obj, "id")
                and response_obj.get("id", None) is not None
            ):
                generation_id = litellm.utils.get_logging_id(
                    start_time, response_obj
                )
            _usage_obj = getattr(response_obj, "usage", None)

            if _usage_obj:
                usage = {
                    "prompt_tokens": _usage_obj.prompt_tokens,
                    "completion_tokens": _usage_obj.completion_tokens,
                    "total_cost": cost if self._supports_costs() else None,
                }
        generation_name = clean_metadata.pop("generation_name", None)
        if generation_name is None:
            # if `generation_name` is None, use sensible default values
            # If using litellm proxy user `key_alias` if not None
            # If `key_alias` is None, just log `litellm-{call_type}` as the generation name
            _user_api_key_alias = cast(
                Optional[str], clean_metadata.get("user_api_key_alias", None)
            )
            generation_name = (
                f"litellm-{cast(str, kwargs.get('call_type', 'completion'))}"
            )
            if _user_api_key_alias is not None:
                generation_name = f"litellm:{_user_api_key_alias}"

        if response_obj is not None:
            system_fingerprint = getattr(response_obj, "system_fingerprint", None)
        else:
            system_fingerprint = None

        if system_fingerprint is not None:
            optional_params["system_fingerprint"] = system_fingerprint

        generation_params = {
            "name": generation_name,
            "id": clean_metadata.pop("generation_id", generation_id),
            "start_time": start_time,
            "end_time": end_time,
            "model": kwargs["model"],
            "model_parameters": optional_params,
            "input": input if not mask_input else "redacted-by-litellm",
            "output": output if not mask_output else "redacted-by-litellm",
            "usage": usage,
            "metadata": log_requester_metadata(clean_metadata),
            "level": level,
            "version": clean_metadata.pop("version", None),
        }

        # Promote every metadata entry whose key starts with "generation_"
        for key in list(
            filter(lambda k: k.startswith("generation_"), clean_metadata.keys())
        ):
            if stripped not in generation_params:
                generation_params[stripped] = clean_metadata[key]

        parent_observation_id = metadata.get("parent_observation_id", None)
        if parent_observation_id is not None:
            generation_params["parent_observation_id"] = parent_observation_id

        if self._supports_prompt():
            generation_params = _add_prompt_to_generation_params(
                generation_params=generation_params,
                clean_metadata=clean_metadata,
                prompt_management_metadata=prompt_management_metadata,
                langfuse_client=self.Langfuse,
            )
        if output is not None and isinstance(output, str) and level == "ERROR":
            generation_params["status_message"] = output

        if self._supports_completion_start_time():
            generation_params["completion_start_time"] = kwargs.get(
                "completion_start_time", None
            )

        generation_client = trace.generation(**generation_params)

        return generation_client.trace_id, generation_id
    except Exception:
        verbose_logger.error(f"Langfuse Layer Error - {traceback.format_exc()}")
        return None, None

def anthropic_messages_pt(  # noqa: PLR0915
    messages: List[AllMessageValues],
    model: str,
    llm_provider: str,
) -> List[
    Union[
        AnthropicMessagesUserMessageParam,
        AnthopicMessagesAssistantMessageParam,
    ]
]:
    """
    format messages for anthropic
    1. Anthropic supports roles like "user" and "assistant" (system prompt sent separately)
    2. The first message always needs to be of role "user"
    3. Each message must alternate between "user" and "assistant" (this is not addressed as now by litellm)
    4. final assistant content cannot end with trailing whitespace (anthropic raises an error otherwise)
    5. System messages are a separate param to the Messages API
    6. Ensure we only accept role, content. (message.name is not supported)
    """
    # add role=tool support to allow function call result/error submission
    user_message_types = {"user", "tool", "function"}
    # reformat messages to ensure user/assistant are alternating, if there's either 2 consecutive 'user' messages or 2 consecutive 'assistant' message, merge them.
    new_messages: List[
        Union[
            AnthropicMessagesUserMessageParam,
            AnthopicMessagesAssistantMessageParam,
        ]
    ] = []

    if len(messages) == 0:
        if not litellm.modify_params:
            raise litellm.BadRequestError(
                message=f"Anthropic requires at least one non-system message. Either provide one, or set `litellm.modify_params = True` // `litellm_settings::modify_params: True` to add the dummy user message - {DEFAULT_USER_CONTINUE_MESSAGE_TYPED}.",
                model=model,
                llm_provider=llm_provider,
            )
        else:
            messages.append(DEFAULT_USER_CONTINUE_MESSAGE_TYPED)

    msg_i = 0
    while msg_i < len(messages):
        user_content: List[AnthropicMessagesUserMessageValues] = []
        init_msg_i = msg_i
        if isinstance(messages[msg_i], BaseModel):
            messages[msg_i] = dict(messages[msg_i])  # type: ignore
        ## MERGE CONSECUTIVE USER CONTENT ##
        while msg_i < len(messages) and messages[msg_i]["role"] in user_message_types:
            user_message_types_block: Union[
                ChatCompletionToolMessage,
                ChatCompletionUserMessage,
                ChatCompletionFunctionMessage,
            ] = messages[
                msg_i
            ]  # type: ignore
            if user_message_types_block["role"] == "user":
                if isinstance(user_message_types_block["content"], list):
                    for m in user_message_types_block["content"]:
                        if m.get("type", "") == "image_url":
                            m = cast(ChatCompletionImageObject, m)
                            format: Optional[str] = None
                            if isinstance(m["image_url"], str):
                                image_chunk = convert_to_anthropic_image_obj(
                                    openai_image_url=m["image_url"], format=None
                                )
                            else:
                                format = m["image_url"].get("format")
                                image_chunk = convert_to_anthropic_image_obj(
                                    openai_image_url=m["image_url"]["url"],
                                    format=format,
                                )

                            _anthropic_content_element = (
                                _anthropic_content_element_factory(image_chunk)
                            )
                            _content_element = add_cache_control_to_content(
                                anthropic_content_element=_anthropic_content_element,
                                orignal_content_element=dict(m),
                            )

                            if "cache_control" in _content_element:
                                _anthropic_content_element["cache_control"] = (
                                    _content_element["cache_control"]
                                )
                            user_content.append(_anthropic_content_element)
                        elif m.get("type", "") == "text":
                            m = cast(ChatCompletionTextObject, m)
                            _anthropic_text_content_element = (
                                AnthropicMessagesTextParam(
                                    type="text",
                                    text=m["text"],
                                )
                            )
                            _content_element = add_cache_control_to_content(
                                anthropic_content_element=_anthropic_text_content_element,
                                orignal_content_element=dict(m),
                            )
                            _content_element = cast(
                                AnthropicMessagesTextParam, _content_element
                            )

                            user_content.append(_content_element)
                        elif m.get("type", "") == "document":
                            user_content.append(cast(AnthropicMessagesDocumentParam, m))
                        elif m.get("type", "") == "file":
                            user_content.append(
                                anthropic_process_openai_file_message(
                                    cast(ChatCompletionFileObject, m)
                                )
                            )
                elif isinstance(user_message_types_block["content"], str):
                    _anthropic_content_text_element: AnthropicMessagesTextParam = {
                        "type": "text",
                        "text": user_message_types_block["content"],
                    }
                    _content_element = add_cache_control_to_content(
                        anthropic_content_element=_anthropic_content_text_element,
                        orignal_content_element=dict(user_message_types_block),
                    )

                    if "cache_control" in _content_element:
                        _anthropic_content_text_element["cache_control"] = (
                            _content_element["cache_control"]
                        )

                    user_content.append(_anthropic_content_text_element)

            elif (
                user_message_types_block["role"] == "tool"
                or user_message_types_block["role"] == "function"
            ):
                # OpenAI's tool message content will always be a string
                user_content.append(
                    convert_to_anthropic_tool_result(user_message_types_block)
                )

            msg_i += 1

        if user_content:
            new_messages.append({"role": "user", "content": user_content})

        assistant_content: List[AnthropicMessagesAssistantMessageValues] = []
        ## MERGE CONSECUTIVE ASSISTANT CONTENT ##
        while msg_i < len(messages) and messages[msg_i]["role"] == "assistant":
            assistant_content_block: ChatCompletionAssistantMessage = messages[msg_i]  # type: ignore

            thinking_blocks = assistant_content_block.get("thinking_blocks", None)
            if (
                thinking_blocks is not None
            ):  # IMPORTANT: ADD THIS FIRST, ELSE ANTHROPIC WILL RAISE AN ERROR
                assistant_content.extend(thinking_blocks)
            if "content" in assistant_content_block and isinstance(
                assistant_content_block["content"], list
            ):
                for m in assistant_content_block["content"]:
                    # handle thinking blocks
                    thinking_block = cast(str, m.get("thinking", ""))
                    text_block = cast(str, m.get("text", ""))
                    if (
                        m.get("type", "") == "thinking" and len(thinking_block) > 0
                    ):  # don't pass empty text blocks. anthropic api raises errors.
                        anthropic_message: Union[
                            ChatCompletionThinkingBlock,
                            AnthropicMessagesTextParam,
                        ] = cast(ChatCompletionThinkingBlock, m)
                        assistant_content.append(anthropic_message)
                    # handle text
                    elif (
                        m.get("type", "") == "text" and len(text_block) > 0
                    ):  # don't pass empty text blocks. anthropic api raises errors.
                        anthropic_message = AnthropicMessagesTextParam(
                            type="text", text=text_block
                        )
                        _cached_message = add_cache_control_to_content(
                            anthropic_content_element=anthropic_message,
                            orignal_content_element=dict(m),
                        )

                        assistant_content.append(
                            cast(AnthropicMessagesTextParam, _cached_message)
                        )
            elif (
                "content" in assistant_content_block
                and isinstance(assistant_content_block["content"], str)
                and assistant_content_block[
                    "content"
                ]  # don't pass empty text blocks. anthropic api raises errors.
            ):
                _anthropic_text_content_element = AnthropicMessagesTextParam(
                    type="text",
                    text=assistant_content_block["content"],
                )

                _content_element = add_cache_control_to_content(
                    anthropic_content_element=_anthropic_text_content_element,
                    orignal_content_element=dict(assistant_content_block),
                )

                if "cache_control" in _content_element:
                    _anthropic_text_content_element["cache_control"] = _content_element[
                        "cache_control"
                    ]

                assistant_content.append(_anthropic_text_content_element)

            assistant_tool_calls = assistant_content_block.get("tool_calls")
            if (
                assistant_tool_calls is not None
            ):  # support assistant tool invoke conversion
                assistant_content.extend(
                    convert_to_anthropic_tool_invoke(assistant_tool_calls)
                )

            assistant_function_call = assistant_content_block.get("function_call")

            if assistant_function_call is not None:
                assistant_content.extend(
                    convert_function_to_anthropic_tool_invoke(assistant_function_call)
                )

            msg_i += 1

        if assistant_content:
            new_messages.append({"role": "assistant", "content": assistant_content})

        if msg_i == init_msg_i:  # prevent infinite loops
            raise litellm.BadRequestError(
                message=BAD_MESSAGE_ERROR_STR + f"passed in {messages[msg_i]}",
                model=model,
                llm_provider=llm_provider,
            )

    if len(new_messages) > 0 and new_messages[-1]["role"] == "assistant":
        if isinstance(new_messages[-1]["content"], str):
            new_messages[-1]["content"] = new_messages[-1]["content"].rstrip()
        elif isinstance(new_messages[-1]["content"], list):
            for content in new_messages[-1]["content"]:
                if isinstance(content, dict) and content["type"] == "text":
                    content["text"] = content[
                        "text"
                    ].rstrip()  # no trailing whitespace for final assistant message

    return new_messages

def anthropic_messages_pt(  # noqa: PLR0915
    messages: List[AllMessageValues],
    model: str,
    llm_provider: str,
) -> List[
    Union[
        AnthropicMessagesUserMessageParam,
        AnthopicMessagesAssistantMessageParam,
    ]
]:
    """
    format messages for anthropic
    1. Anthropic supports roles like "user" and "assistant" (system prompt sent separately)
    2. The first message always needs to be of role "user"
    3. Each message must alternate between "user" and "assistant" (this is not addressed as now by litellm)
    4. final assistant content cannot end with trailing whitespace (anthropic raises an error otherwise)
    5. System messages are a separate param to the Messages API
    6. Ensure we only accept role, content. (message.name is not supported)
    """
    # add role=tool support to allow function call result/error submission
    user_message_types = {"user", "tool", "function"}
    # reformat messages to ensure user/assistant are alternating, if there's either 2 consecutive 'user' messages or 2 consecutive 'assistant' message, merge them.
    new_messages: List[
        Union[
            AnthropicMessagesUserMessageParam,
            AnthopicMessagesAssistantMessageParam,
        ]
    ] = []

    if len(messages) == 0:
        if not litellm.modify_params:
            raise litellm.BadRequestError(
                message=f"Anthropic requires at least one non-system message. Either provide one, or set `litellm.modify_params = True` // `litellm_settings::modify_params: True` to add the dummy user message - {DEFAULT_USER_CONTINUE_MESSAGE_TYPED}.",
                model=model,
                llm_provider=llm_provider,
            )
        else:
            messages.append(DEFAULT_USER_CONTINUE_MESSAGE_TYPED)

    msg_i = 0
    while msg_i < len(messages):
        user_content: List[AnthropicMessagesUserMessageValues] = []
        init_msg_i = msg_i
        if isinstance(messages[msg_i], BaseModel):
            messages[msg_i] = dict(messages[msg_i])  # type: ignore
        ## MERGE CONSECUTIVE USER CONTENT ##
        while msg_i < len(messages) and messages[msg_i]["role"] in user_message_types:
            user_message_types_block: Union[
                ChatCompletionToolMessage,
                ChatCompletionUserMessage,
                ChatCompletionFunctionMessage,
            ] = messages[
                msg_i
            ]  # type: ignore
            if user_message_types_block["role"] == "user":
                if isinstance(user_message_types_block["content"], list):
                    for m in user_message_types_block["content"]:
                        if m.get("type", "") == "image_url":
                            m = cast(ChatCompletionImageObject, m)
                            format: Optional[str] = None
                            if isinstance(m["image_url"], str):
                                image_chunk = convert_to_anthropic_image_obj(
                                    openai_image_url=m["image_url"], format=None
                                )
                            else:
                                format = m["image_url"].get("format")
                                image_chunk = convert_to_anthropic_image_obj(
                                    openai_image_url=m["image_url"]["url"],
                                    format=format,
                                )

                            _anthropic_content_element = (
                                _anthropic_content_element_factory(image_chunk)
                            )
                            _content_element = add_cache_control_to_content(
                                anthropic_content_element=_anthropic_content_element,
                                orignal_content_element=dict(m),
                            )

                            if "cache_control" in _content_element:
                                _anthropic_content_element["cache_control"] = (
                                    _content_element["cache_control"]
                                )
                            user_content.append(_anthropic_content_element)
                        elif m.get("type", "") == "text":
                            m = cast(ChatCompletionTextObject, m)
                            _anthropic_text_content_element = (
                                AnthropicMessagesTextParam(
                                    type="text",
                                    text=m["text"],
                                )
                            )
                            _content_element = add_cache_control_to_content(
                                anthropic_content_element=_anthropic_text_content_element,
                                orignal_content_element=dict(m),
                            )
                            _content_element = cast(
                                AnthropicMessagesTextParam, _content_element
                            )

                            user_content.append(_content_element)
                        elif m.get("type", "") == "document":
                            user_content.append(cast(AnthropicMessagesDocumentParam, m))
                        elif m.get("type", "") == "file":
                            user_content.append(
                                anthropic_process_openai_file_message(
                                    cast(ChatCompletionFileObject, m)
                                )
                            )
                elif isinstance(user_message_types_block["content"], str):
                    _anthropic_content_text_element: AnthropicMessagesTextParam = {
                        "type": "text",
                        "text": user_message_types_block["content"],
                    }
                    _content_element = add_cache_control_to_content(
                        anthropic_content_element=_anthropic_content_text_element,
                        orignal_content_element=dict(user_message_types_block),
                    )

                    if "cache_control" in _content_element:
                        _anthropic_content_text_element["cache_control"] = (
                            _content_element["cache_control"]
                        )

                    user_content.append(_anthropic_content_text_element)

            elif (
                user_message_types_block["role"] == "tool"
                or user_message_types_block["role"] == "function"
            ):
                # OpenAI's tool message content will always be a string
                user_content.append(
                    convert_to_anthropic_tool_result(user_message_types_block)
                )

            msg_i += 1

        if user_content:
            new_messages.append({"role": "user", "content": user_content})

        assistant_content: List[AnthropicMessagesAssistantMessageValues] = []
        ## MERGE CONSECUTIVE ASSISTANT CONTENT ##
        while msg_i < len(messages) and messages[msg_i]["role"] == "assistant":
            assistant_content_block: ChatCompletionAssistantMessage = messages[msg_i]  # type: ignore

            thinking_blocks = assistant_content_block.get("thinking_blocks", None)
            if (
                thinking_blocks is not None
            ):  # IMPORTANT: ADD THIS FIRST, ELSE ANTHROPIC WILL RAISE AN ERROR
                assistant_content.extend(thinking_blocks)
            if "content" in assistant_content_block and isinstance(
                assistant_content_block["content"], list
            ):
                for m in assistant_content_block["content"]:
                    # handle thinking blocks
                    thinking_block = cast(str, m.get("thinking", ""))
                    text_block = cast(str, m.get("text", ""))
                    if (
                        m.get("type", "") == "thinking" and len(thinking_block) > 0
                    ):  # don't pass empty text blocks. anthropic api raises errors.
                        anthropic_message: Union[
                            ChatCompletionThinkingBlock,
                            AnthropicMessagesTextParam,
                        ] = cast(ChatCompletionThinkingBlock, m)
                        assistant_content.append(anthropic_message)
                    # handle text
                    elif (
                        m.get("type", "") == "text" and len(text_block) > 0
                    ):  # don't pass empty text blocks. anthropic api raises errors.
                        anthropic_message = AnthropicMessagesTextParam(
                            type="text", text=text_block
                        )
                        _cached_message = add_cache_control_to_content(
                            anthropic_content_element=anthropic_message,
                            orignal_content_element=dict(m),
                        )

                        assistant_content.append(
                            cast(AnthropicMessagesTextParam, _cached_message)
                        )
            elif (
                "content" in assistant_content_block
                and isinstance(assistant_content_block["content"], str)
                and assistant_content_block[
                    "content"
                ]  # don't pass empty text blocks. anthropic api raises errors.
            ):
                _anthropic_text_content_element = AnthropicMessagesTextParam(
                    type="text",
                    text=assistant_content_block["content"],
                )

                _content_element = add_cache_control_to_content(
                    anthropic_content_element=_anthropic_text_content_element,
                    orignal_content_element=dict(assistant_content_block),
                )

                if "cache_control" in _content_element:
                    _anthropic_text_content_element["cache_control"] = _content_element[
                        "cache_control"
                    ]

                assistant_content.append(_anthropic_text_content_element)

            assistant_tool_calls = assistant_content_block.get("tool_calls")
            if (
                assistant_tool_calls is not None
            ):  # support assistant tool invoke conversion
                assistant_content.extend(
                    convert_to_anthropic_tool_invoke(assistant_tool_calls)
                )

            assistant_function_call = assistant_content_block.get("function_call")

            if assistant_function_call is not None:
                assistant_content.extend(
                    convert_function_to_anthropic_tool_invoke(assistant_function_call)
                )

            msg_i += 1

        if assistant_content:
            new_messages.append({"role": "assistant", "content": assistant_content})

        if msg_i == init_msg_i:  # prevent infinite loops
            raise litellm.BadRequestError(
                message=BAD_MESSAGE_ERROR_STR + f"passed in {messages[msg_i]}",
                model=model,
                llm_provider=llm_provider,
            )

    if len(new_messages) > 0 and new_messages[-1]["role"] == "assistant":
        if isinstance(new_messages[-1]["content"], str):
            new_messages[-1]["content"] = new_messages[-1]["content"].rstrip()
        elif isinstance(new_messages[-1]["content"], list):
            for content in new_messages[-1]["content"]:
                if isinstance(content, dict) and content["type"] == "text":
                    content["text"] = content[
                        "text"
                    ].rstrip()  # no trailing whitespace for final assistant message

    return new_messages

def infer_protocol_value(
    value: Any,
) -> Literal[
    "string_value",
    "number_value",
    "bool_value",
    "struct_value",
    "list_value",
    "null_value",
    "unknown",
]:
    if value is None:
        return "null_value"
    if isinstance(value, int) or isinstance(value, float):
        return "number_value"
    if isinstance(value, str):
        return "string_value"
    if isinstance(value, bool):
        return "bool_value"
    if isinstance(value, dict):
        return "struct_value"
    if isinstance(value, list):
        return "list_value"

    return "unknown"

def _gemini_tool_call_invoke_helper(
    function_call_params: ChatCompletionToolCallFunctionChunk,
) -> Optional[VertexFunctionCall]:
    name = function_call_params.get("name", "") or ""
    arguments = function_call_params.get("arguments", "")
    if (
        isinstance(arguments, str) and len(arguments) == 0
    ):  # pass empty dict, if arguments is empty string - prevents call from failing
        arguments_dict = {
            "type": "object",
        }
    else:
        arguments_dict = json.loads(arguments)
    function_call = VertexFunctionCall(
        name=name,
        args=arguments_dict,
    )
    return function_call

def convert_to_gemini_tool_call_invoke(
    message: ChatCompletionAssistantMessage,
) -> List[VertexPartType]:
    """
    OpenAI tool invokes:
    {
      "role": "assistant",
      "content": null,
      "tool_calls": [
        {
          "id": "call_abc123",
          "type": "function",
          "function": {
            "name": "get_current_weather",
            "arguments": "{\n\"location\": \"Boston, MA\"\n}"
          }
        }
      ]
    },
    """
    """
    Gemini tool call invokes:
    {
      "role": "model",
      "parts": [
        {
          "functionCall": {
            "name": "get_current_weather",
            "args": {
              "unit": "fahrenheit",
              "predicted_temperature": 45,
              "location": "Boston, MA",
            }
          }
        }
      ]
    }
    """

    """
    - json.load the arguments
    """
    try:
        _parts_list: List[VertexPartType] = []
        tool_calls = message.get("tool_calls", None)
        function_call = message.get("function_call", None)
        if tool_calls is not None:
            for tool in tool_calls:
                if "function" in tool:
                    gemini_function_call: Optional[VertexFunctionCall] = (
                        _gemini_tool_call_invoke_helper(
                            function_call_params=tool["function"]
                        )
                    )
                    if gemini_function_call is not None:
                        _parts_list.append(
                            VertexPartType(function_call=gemini_function_call)
                        )
                    else:  # don't silently drop params. Make it clear to user what's happening.
                        raise Exception(
                            "function_call missing. Received tool call with 'type': 'function'. No function call in argument - {}".format(
                                tool
                            )
                        )
        elif function_call is not None:
            gemini_function_call = _gemini_tool_call_invoke_helper(
                function_call_params=function_call
            )
            if gemini_function_call is not None:
                _parts_list.append(VertexPartType(function_call=gemini_function_call))
            else:  # don't silently drop params. Make it clear to user what's happening.
                raise Exception(
                    "function_call missing. Received tool call with 'type': 'function'. No function call in argument - {}".format(
                        message
                    )
                )
        return _parts_list
    except Exception as e:
        raise Exception(
            "Unable to convert openai tool calls={} to gemini tool calls. Received error={}".format(
                message, str(e)
            )
        )

def _add_reasoning_system_prompt_if_needed(
    self, 
    messages: List[AllMessageValues], 
    optional_params: dict
) -> List[AllMessageValues]:
    """
    Add reasoning system prompt for Mistral magistral models when reasoning_effort is specified.
    """
    if not optional_params.get("_add_reasoning_prompt", False):
        return messages

    # Check if there's already a system message
    has_system_message = any(msg.get("role") == "system" for msg in messages)

    if has_system_message:
        # Prepend reasoning instructions to existing system message
        for i, msg in enumerate(messages):
            if msg.get("role") == "system":
                existing_content = msg.get("content", "")
                reasoning_prompt = self._get_mistral_reasoning_system_prompt()

                # Handle both string and list content
                if isinstance(existing_content, str):
                    # String content - prepend reasoning prompt
                    new_content = f"{reasoning_prompt}\n\n{existing_content}"
                elif isinstance(existing_content, list):
                    # List content - prepend reasoning prompt as text block
                    new_content = [
                        {"type": "text", "text": reasoning_prompt + "\n\n"}
                    ] + existing_content
                else:
                    # Fallback for any other type - convert to string
                    new_content = f"{reasoning_prompt}\n\n{str(existing_content)}"

                messages[i] = cast(AllMessageValues, {
                    **msg,
                    "content": new_content
                })
                break
    else:
        # Add new system message with reasoning instructions
        reasoning_message: AllMessageValues = cast(AllMessageValues, {
            "role": "system",
            "content": self._get_mistral_reasoning_system_prompt()
        })
        messages = [reasoning_message] + messages

    # Remove the internal flag
    optional_params.pop("_add_reasoning_prompt", None)
    return messages

def _execute_tool_action(self, tools_dict, call):
    parser = ToolActionParser(self.llm.__class__.__name__)
    tool_id, action_name, call_args = parser.parse_args(call)

    call_id = getattr(call, "id", None) or str(uuid.uuid4())

    # Check if parsing failed
    if tool_id is None or action_name is None:
        error_message = f"Error: Failed to parse LLM tool call. Tool name: {getattr(call, 'name', 'unknown')}"
        logger.error(error_message)

        tool_call_data = {
            "tool_name": "unknown",
            "call_id": call_id,
            "action_name": getattr(call, 'name', 'unknown'),
            "arguments": call_args or {},
            "result": f"Failed to parse tool call. Invalid tool name format: {getattr(call, 'name', 'unknown')}",
        }
        yield {"type": "tool_call", "data": {**tool_call_data, "status": "error"}}
        self.tool_calls.append(tool_call_data)
        return f"Failed to parse tool call.", call_id

    # Check if tool_id exists in available tools
    if tool_id not in tools_dict:
        error_message = f"Error: Tool ID '{tool_id}' extracted from LLM call not found in available tools_dict. Available IDs: {list(tools_dict.keys())}"
        logger.error(error_message)

        # Return error result
        tool_call_data = {
            "tool_name": "unknown",
            "call_id": call_id,
            "action_name": f"{action_name}_{tool_id}",
            "arguments": call_args,
            "result": f"Tool with ID {tool_id} not found. Available tools: {list(tools_dict.keys())}",
        }
        yield {"type": "tool_call", "data": {**tool_call_data, "status": "error"}}
        self.tool_calls.append(tool_call_data)
        return f"Tool with ID {tool_id} not found.", call_id

    tool_call_data = {
        "tool_name": tools_dict[tool_id]["name"],
        "call_id": call_id,
        "action_name": f"{action_name}_{tool_id}",
        "arguments": call_args,
    }
    yield {"type": "tool_call", "data": {**tool_call_data, "status": "pending"}}

    tool_data = tools_dict[tool_id]
    action_data = (
        tool_data["config"]["actions"][action_name]
        if tool_data["name"] == "api_tool"
        else next(
            action
            for action in tool_data["actions"]
            if action["name"] == action_name
        )
    )

    query_params, headers, body, parameters = {}, {}, {}, {}
    param_types = {
        "query_params": query_params,
        "headers": headers,
        "body": body,
        "parameters": parameters,
    }

    for param_type, target_dict in param_types.items():
        if param_type in action_data and action_data[param_type].get("properties"):
            for param, details in action_data[param_type]["properties"].items():
                if param not in call_args and "value" in details:
                    target_dict[param] = details["value"]
    for param, value in call_args.items():
        for param_type, target_dict in param_types.items():
            if param_type in action_data and param in action_data[param_type].get(
                "properties", {}
            ):
                target_dict[param] = value
    tm = ToolManager(config={})
    tool = tm.load_tool(
        tool_data["name"],
        tool_config=(
            {
                "url": tool_data["config"]["actions"][action_name]["url"],
                "method": tool_data["config"]["actions"][action_name]["method"],
                "headers": headers,
                "query_params": query_params,
            }
            if tool_data["name"] == "api_tool"
            else tool_data["config"]
        ),
    )
    if tool_data["name"] == "api_tool":
        print(
            f"Executing api: {action_name} with query_params: {query_params}, headers: {headers}, body: {body}"
        )
        result = tool.execute_action(action_name, **body)
    else:
        print(f"Executing tool: {action_name} with args: {call_args}")
        result = tool.execute_action(action_name, **parameters)
    tool_call_data["result"] = (
        f"{str(result)[:50]}..." if len(str(result)) > 50 else result
    )

    yield {"type": "tool_call", "data": {**tool_call_data, "status": "completed"}}
    self.tool_calls.append(tool_call_data)

    return result, call_id

def test():
    branch_commit = find_branch_point("origin/master")
    files = diff_files(branch_commit)
    print(files)
    rc, errors = run_ruff(files, fix=True)
    if errors:
        print(errors)
    else:
        print("No lint errors found.")
    assert rc == 0

def run_ruff(files, fix):
    if not files:
        return 0, ""
    args = ['--fix'] if fix else []
    res = subprocess.run(
        ['ruff', 'check', f'--config={CONFIG}'] + args + files,
        stdout=subprocess.PIPE,
        encoding='utf-8'
    )
    return res.returncode, res.stdout

