async def ainvoke(
	self, messages: list[BaseMessage], output_format: type[T] | None = None
) -> ChatInvokeCompletion[T] | ChatInvokeCompletion[str]:
	"""
	Invoke the model with the given messages.

	Args:
		messages: List of chat messages
		output_format: Optional Pydantic model class for structured output

	Returns:
		Either a string response or an instance of output_format
	"""

	# Serialize messages to Google format with the include_system_in_user flag
	contents, system_instruction = GoogleMessageSerializer.serialize_messages(
		messages, include_system_in_user=self.include_system_in_user
	)

	# Build config dictionary starting with user-provided config
	config: types.GenerateContentConfigDict = {}
	if self.config:
		config = self.config.copy()

	# Apply model-specific configuration (these can override config)
	if self.temperature is not None:
		config['temperature'] = self.temperature

	# Add system instruction if present
	if system_instruction:
		config['system_instruction'] = system_instruction

	if self.top_p is not None:
		config['top_p'] = self.top_p

	if self.seed is not None:
		config['seed'] = self.seed

	if self.thinking_budget is not None:
		thinking_config_dict: types.ThinkingConfigDict = {'thinking_budget': self.thinking_budget}
		config['thinking_config'] = thinking_config_dict

	async def _make_api_call():
		if output_format is None:
			# Return string response
			response = await self.get_client().aio.models.generate_content(
				model=self.model,
				contents=contents,  # type: ignore
				config=config,
			)

			# Handle case where response.text might be None
			text = response.text or ''

			usage = self._get_usage(response)

			return ChatInvokeCompletion(
				completion=text,
				usage=usage,
			)

		else:
			# Handle structured output
			if self.supports_structured_output:
				# Use native JSON mode
				config['response_mime_type'] = 'application/json'
				# Convert Pydantic model to Gemini-compatible schema
				optimized_schema = SchemaOptimizer.create_optimized_json_schema(output_format)

				gemini_schema = self._fix_gemini_schema(optimized_schema)
				config['response_schema'] = gemini_schema

				response = await self.get_client().aio.models.generate_content(
					model=self.model,
					contents=contents,
					config=config,
				)

				usage = self._get_usage(response)

				# Handle case where response.parsed might be None
				if response.parsed is None:
					# When using response_schema, Gemini returns JSON as text
					if response.text:
						try:
							# Parse the JSON text and validate with the Pydantic model
							parsed_data = json.loads(response.text)
							return ChatInvokeCompletion(
								completion=output_format.model_validate(parsed_data),
								usage=usage,
							)
						except (json.JSONDecodeError, ValueError) as e:
							raise ModelProviderError(
								message=f'Failed to parse or validate response: {str(e)}',
								status_code=500,
								model=self.model,
							) from e
					else:
						raise ModelProviderError(
							message='No response from model',
							status_code=500,
							model=self.model,
						)

				# Ensure we return the correct type
				if isinstance(response.parsed, output_format):
					return ChatInvokeCompletion(
						completion=response.parsed,
						usage=usage,
					)
				else:
					# If it's not the expected type, try to validate it
					return ChatInvokeCompletion(
						completion=output_format.model_validate(response.parsed),
						usage=usage,
					)
			else:
				# Fallback: Request JSON in the prompt for models without native JSON mode
				# Add JSON instruction to the last message
				if messages and isinstance(messages[-1].content, str):
					json_instruction = f"\n\nPlease respond with a valid JSON object that matches this schema: {SchemaOptimizer.create_optimized_json_schema(output_format)}"
					messages[-1].content += json_instruction

				# Re-serialize with modified messages
				contents, _ = GoogleMessageSerializer.serialize_messages(
					messages, include_system_in_user=self.include_system_in_user
				)

				response = await self.get_client().aio.models.generate_content(
					model=self.model,
					contents=contents,  # type: ignore
					config=config,
				)

				usage = self._get_usage(response)

				# Try to extract JSON from the text response
				if response.text:
					try:
						# Try to find JSON in the response
						text = response.text.strip()

						# Common patterns: JSON wrapped in markdown code blocks
						if text.startswith('```json') and text.endswith('```'):
							text = text[7:-3].strip()
						elif text.startswith('```') and text.endswith('```'):
							text = text[3:-3].strip()

						# Parse and validate
						parsed_data = json.loads(text)
						return ChatInvokeCompletion(
							completion=output_format.model_validate(parsed_data),
							usage=usage,
						)
					except (json.JSONDecodeError, ValueError) as e:
						raise ModelProviderError(
							message=f'Model does not support JSON mode and failed to parse JSON from text response: {str(e)}',
							status_code=500,
							model=self.model,
						) from e
				else:
					raise ModelProviderError(
						message='No response from model',
						status_code=500,
						model=self.model,
					)

	try:
		# Use manual retry loop for Google API calls
		last_exception = None
		for attempt in range(10):  # Match our 10 retry attempts from other providers
			try:
				return await _make_api_call()
			except Exception as e:
				last_exception = e
				if not _is_retryable_error(e) or attempt == 9:  # Last attempt
					break

				# Simple exponential backoff
				import asyncio

				delay = min(60.0, 1.0 * (2.0**attempt))  # Cap at 60s
				await asyncio.sleep(delay)

		# Re-raise the last exception if all retries failed
		if last_exception:
			raise last_exception
		else:
			# This should never happen, but ensure we don't return None
			raise ModelProviderError(
				message='All retry attempts failed without exception',
				status_code=500,
				model=self.name,
			)

	except Exception as e:
		# Handle specific Google API errors
		error_message = str(e)
		status_code: int | None = None

		# Check if this is a rate limit error
		if any(
			indicator in error_message.lower()
			for indicator in ['rate limit', 'resource exhausted', 'quota exceeded', 'too many requests', '429']
		):
			status_code = 429
		elif any(
			indicator in error_message.lower()
			for indicator in ['service unavailable', 'internal server error', 'bad gateway', '503', '502', '500']
		):
			status_code = 503

		# Try to extract status code if available
		if hasattr(e, 'response'):
			response_obj = getattr(e, 'response', None)
			if response_obj and hasattr(response_obj, 'status_code'):
				status_code = getattr(response_obj, 'status_code', None)

		raise ModelProviderError(
			message=error_message,
			status_code=status_code or 502,  # Use default if None
			model=self.name,
		) from e

async def ainvoke(
	self, messages: list[BaseMessage], output_format: type[T] | None = None
) -> ChatInvokeCompletion[T] | ChatInvokeCompletion[str]:
	"""
	Invoke the model with the given messages.

	Args:
		messages: List of chat messages
		output_format: Optional Pydantic model class for structured output

	Returns:
		Either a string response or an instance of output_format
	"""

	# Serialize messages to Google format with the include_system_in_user flag
	contents, system_instruction = GoogleMessageSerializer.serialize_messages(
		messages, include_system_in_user=self.include_system_in_user
	)

	# Build config dictionary starting with user-provided config
	config: types.GenerateContentConfigDict = {}
	if self.config:
		config = self.config.copy()

	# Apply model-specific configuration (these can override config)
	if self.temperature is not None:
		config['temperature'] = self.temperature

	# Add system instruction if present
	if system_instruction:
		config['system_instruction'] = system_instruction

	if self.top_p is not None:
		config['top_p'] = self.top_p

	if self.seed is not None:
		config['seed'] = self.seed

	if self.thinking_budget is not None:
		thinking_config_dict: types.ThinkingConfigDict = {'thinking_budget': self.thinking_budget}
		config['thinking_config'] = thinking_config_dict

	async def _make_api_call():
		if output_format is None:
			# Return string response
			response = await self.get_client().aio.models.generate_content(
				model=self.model,
				contents=contents,  # type: ignore
				config=config,
			)

			# Handle case where response.text might be None
			text = response.text or ''

			usage = self._get_usage(response)

			return ChatInvokeCompletion(
				completion=text,
				usage=usage,
			)

		else:
			# Handle structured output
			if self.supports_structured_output:
				# Use native JSON mode
				config['response_mime_type'] = 'application/json'
				# Convert Pydantic model to Gemini-compatible schema
				optimized_schema = SchemaOptimizer.create_optimized_json_schema(output_format)

				gemini_schema = self._fix_gemini_schema(optimized_schema)
				config['response_schema'] = gemini_schema

				response = await self.get_client().aio.models.generate_content(
					model=self.model,
					contents=contents,
					config=config,
				)

				usage = self._get_usage(response)

				# Handle case where response.parsed might be None
				if response.parsed is None:
					# When using response_schema, Gemini returns JSON as text
					if response.text:
						try:
							# Parse the JSON text and validate with the Pydantic model
							parsed_data = json.loads(response.text)
							return ChatInvokeCompletion(
								completion=output_format.model_validate(parsed_data),
								usage=usage,
							)
						except (json.JSONDecodeError, ValueError) as e:
							raise ModelProviderError(
								message=f'Failed to parse or validate response: {str(e)}',
								status_code=500,
								model=self.model,
							) from e
					else:
						raise ModelProviderError(
							message='No response from model',
							status_code=500,
							model=self.model,
						)

				# Ensure we return the correct type
				if isinstance(response.parsed, output_format):
					return ChatInvokeCompletion(
						completion=response.parsed,
						usage=usage,
					)
				else:
					# If it's not the expected type, try to validate it
					return ChatInvokeCompletion(
						completion=output_format.model_validate(response.parsed),
						usage=usage,
					)
			else:
				# Fallback: Request JSON in the prompt for models without native JSON mode
				# Add JSON instruction to the last message
				if messages and isinstance(messages[-1].content, str):
					json_instruction = f"\n\nPlease respond with a valid JSON object that matches this schema: {SchemaOptimizer.create_optimized_json_schema(output_format)}"
					messages[-1].content += json_instruction

				# Re-serialize with modified messages
				contents, _ = GoogleMessageSerializer.serialize_messages(
					messages, include_system_in_user=self.include_system_in_user
				)

				response = await self.get_client().aio.models.generate_content(
					model=self.model,
					contents=contents,  # type: ignore
					config=config,
				)

				usage = self._get_usage(response)

				# Try to extract JSON from the text response
				if response.text:
					try:
						# Try to find JSON in the response
						text = response.text.strip()

						# Common patterns: JSON wrapped in markdown code blocks
						if text.startswith('```json') and text.endswith('```'):
							text = text[7:-3].strip()
						elif text.startswith('```') and text.endswith('```'):
							text = text[3:-3].strip()

						# Parse and validate
						parsed_data = json.loads(text)
						return ChatInvokeCompletion(
							completion=output_format.model_validate(parsed_data),
							usage=usage,
						)
					except (json.JSONDecodeError, ValueError) as e:
						raise ModelProviderError(
							message=f'Model does not support JSON mode and failed to parse JSON from text response: {str(e)}',
							status_code=500,
							model=self.model,
						) from e
				else:
					raise ModelProviderError(
						message='No response from model',
						status_code=500,
						model=self.model,
					)

	try:
		# Use manual retry loop for Google API calls
		last_exception = None
		for attempt in range(10):  # Match our 10 retry attempts from other providers
			try:
				return await _make_api_call()
			except Exception as e:
				last_exception = e
				if not _is_retryable_error(e) or attempt == 9:  # Last attempt
					break

				# Simple exponential backoff
				import asyncio

				delay = min(60.0, 1.0 * (2.0**attempt))  # Cap at 60s
				await asyncio.sleep(delay)

		# Re-raise the last exception if all retries failed
		if last_exception:
			raise last_exception
		else:
			# This should never happen, but ensure we don't return None
			raise ModelProviderError(
				message='All retry attempts failed without exception',
				status_code=500,
				model=self.name,
			)

	except Exception as e:
		# Handle specific Google API errors
		error_message = str(e)
		status_code: int | None = None

		# Check if this is a rate limit error
		if any(
			indicator in error_message.lower()
			for indicator in ['rate limit', 'resource exhausted', 'quota exceeded', 'too many requests', '429']
		):
			status_code = 429
		elif any(
			indicator in error_message.lower()
			for indicator in ['service unavailable', 'internal server error', 'bad gateway', '503', '502', '500']
		):
			status_code = 503

		# Try to extract status code if available
		if hasattr(e, 'response'):
			response_obj = getattr(e, 'response', None)
			if response_obj and hasattr(response_obj, 'status_code'):
				status_code = getattr(response_obj, 'status_code', None)

		raise ModelProviderError(
			message=error_message,
			status_code=status_code or 502,  # Use default if None
			model=self.name,
		) from e

async def ainvoke(
	self, messages: list[BaseMessage], output_format: type[T] | None = None
) -> ChatInvokeCompletion[T] | ChatInvokeCompletion[str]:
	anthropic_messages, system_prompt = AnthropicMessageSerializer.serialize_messages(messages)

	try:
		if output_format is None:
			# Normal completion without structured output
			response = await self.get_client().messages.create(
				model=self.model,
				messages=anthropic_messages,
				system=system_prompt or NOT_GIVEN,
				**self._get_client_params_for_invoke(),
			)

			# Ensure we have a valid Message object before accessing attributes
			if not isinstance(response, Message):
				raise ModelProviderError(
					message=f'Unexpected response type from Anthropic API: {type(response).__name__}. Response: {str(response)[:200]}',
					status_code=502,
					model=self.name,
				)

			usage = self._get_usage(response)

			# Extract text from the first content block
			first_content = response.content[0]
			if isinstance(first_content, TextBlock):
				response_text = first_content.text
			else:
				# If it's not a text block, convert to string
				response_text = str(first_content)

			return ChatInvokeCompletion(
				completion=response_text,
				usage=usage,
			)

		else:
			# Use tool calling for structured output
			# Create a tool that represents the output format
			tool_name = output_format.__name__
			schema = SchemaOptimizer.create_optimized_json_schema(output_format)

			# Remove title from schema if present (Anthropic doesn't like it in parameters)
			if 'title' in schema:
				del schema['title']

			tool = ToolParam(
				name=tool_name,
				description=f'Extract information in the format of {tool_name}',
				input_schema=schema,
				cache_control=CacheControlEphemeralParam(type='ephemeral'),
			)

			# Force the model to use this tool
			tool_choice = ToolChoiceToolParam(type='tool', name=tool_name)

			response = await self.get_client().messages.create(
				model=self.model,
				messages=anthropic_messages,
				tools=[tool],
				system=system_prompt or NOT_GIVEN,
				tool_choice=tool_choice,
				**self._get_client_params_for_invoke(),
			)

			# Ensure we have a valid Message object before accessing attributes
			if not isinstance(response, Message):
				raise ModelProviderError(
					message=f'Unexpected response type from Anthropic API: {type(response).__name__}. Response: {str(response)[:200]}',
					status_code=502,
					model=self.name,
				)

			usage = self._get_usage(response)

			# Extract the tool use block
			for content_block in response.content:
				if hasattr(content_block, 'type') and content_block.type == 'tool_use':
					# Parse the tool input as the structured output
					try:
						return ChatInvokeCompletion(completion=output_format.model_validate(content_block.input), usage=usage)
					except Exception as e:
						# If validation fails, try to parse it as JSON first
						if isinstance(content_block.input, str):
							data = json.loads(content_block.input)
							return ChatInvokeCompletion(
								completion=output_format.model_validate(data),
								usage=usage,
							)
						raise e

			# If no tool use block found, raise an error
			raise ValueError('Expected tool use in response but none found')

	except APIConnectionError as e:
		raise ModelProviderError(message=e.message, model=self.name) from e
	except RateLimitError as e:
		raise ModelRateLimitError(message=e.message, model=self.name) from e
	except APIStatusError as e:
		raise ModelProviderError(message=e.message, status_code=e.status_code, model=self.name) from e
	except Exception as e:
		raise ModelProviderError(message=str(e), model=self.name) from e

