def last_action(self) -> None | dict:
	"""Last action in history"""
	if self.history and self.history[-1].model_output:
		return self.history[-1].model_output.action[-1].model_dump(exclude_none=True)
	return None

def final_result(self) -> None | str:
	"""Final result from history"""
	if self.history and self.history[-1].result[-1].extracted_content:
		return self.history[-1].result[-1].extracted_content
	return None

def is_successful(self) -> bool | None:
	"""Check if the agent completed successfully - the agent decides in the last step if it was successful or not. None if not done yet."""
	if self.history and len(self.history[-1].result) > 0:
		last_result = self.history[-1].result[-1]
		if last_result.is_done is True:
			return last_result.success
	return None

def urls(self) -> list[str | None]:
	"""Get all unique URLs from history"""
	return [h.state.url if h.state.url is not None else None for h in self.history]

def screenshots(self, n_last: int | None = None, return_none_if_not_screenshot: bool = True) -> list[str | None]:
	"""Get all screenshots from history"""
	if n_last == 0:
		return []
	if n_last is None:
		if return_none_if_not_screenshot:
			return [h.state.screenshot if h.state.screenshot is not None else None for h in self.history]
		else:
			return [h.state.screenshot for h in self.history if h.state.screenshot is not None]
	else:
		if return_none_if_not_screenshot:
			return [h.state.screenshot if h.state.screenshot is not None else None for h in self.history[-n_last:]]
		else:
			return [h.state.screenshot for h in self.history[-n_last:] if h.state.screenshot is not None]

def model_thoughts(self) -> list[AgentBrain]:
	"""Get all thoughts from history"""
	return [h.model_output.current_state for h in self.history if h.model_output]

def model_outputs(self) -> list[AgentOutput]:
	"""Get all model outputs from history"""
	return [h.model_output for h in self.history if h.model_output]

def model_actions(self) -> list[dict]:
	"""Get all actions from history"""
	outputs = []

	for h in self.history:
		if h.model_output:
			for action, interacted_element in zip(h.model_output.action, h.state.interacted_element):
				output = action.model_dump(exclude_none=True)
				output['interacted_element'] = interacted_element
				outputs.append(output)
	return outputs

def action_results(self) -> list[ActionResult]:
	"""Get all results from history"""
	results = []
	for h in self.history:
		results.extend([r for r in h.result if r])
	return results

def extracted_content(self) -> list[str]:
	"""Get all extracted content from history"""
	content = []
	for h in self.history:
		content.extend([r.extracted_content for r in h.result if r.extracted_content])
	return content

def sync_to_disk_sync(self, path: Path) -> None:
	file_path = path / self.full_name
	try:
		md_pdf = MarkdownPdf()
		md_pdf.add_section(Section(self.content))
		md_pdf.save(file_path)
	except Exception as e:
		raise FileSystemError(f"Error: Could not write to file '{self.full_name}'. {str(e)}")

def get_state(self) -> FileSystemState:
	"""Get serializable state of the file system"""
	files_data = {}
	for full_filename, file_obj in self.files.items():
		files_data[full_filename] = {'type': file_obj.__class__.__name__, 'data': file_obj.model_dump()}

	return FileSystemState(
		files=files_data, base_dir=str(self.base_dir), extracted_content_count=self.extracted_content_count
	)

def _get_client_params(self) -> dict[str, Any]:
	"""Prepare client parameters dictionary."""
	# Define base client params
	base_params = {
		'api_key': self.api_key,
		'auth_token': self.auth_token,
		'base_url': self.base_url,
		'timeout': self.timeout,
		'max_retries': self.max_retries,
		'default_headers': self.default_headers,
		'default_query': self.default_query,
	}

	# Create client_params dict with non-None values and non-NotGiven values
	client_params = {}
	for k, v in base_params.items():
		if v is not None and v is not NotGiven():
			client_params[k] = v

	return client_params

